#include <stdint.h>
#include <stddef.h>

/* Number of elements in an array. */
#define ARRAY_LEN(array)  (sizeof(array) / sizeof((array)[0]))

/*
 * Average a block of 12-bit ADC samples.
 *
 * Raised by test: with eight samples in the buffer the reported average is
 * far too low. It was correct back when the buffer was a file-scope array
 * in this module and the function took no arguments.
 */
uint16_t average_samples(const uint16_t samples[], size_t count)
{
    uint32_t total = 0;
    size_t n = ARRAY_LEN(samples);
    size_t i;

    if (count == 0u) {
        return 0u;
    }

    for (i = 0; i < n; i++) {
        total += samples[i];
    }

    return (uint16_t)(total / n);
}

