#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

#define MAX_SAMPLES 64

/* Provided by the candidate in solution.c */
uint16_t average_samples(const uint16_t samples[], size_t count);

/* Deliberately at file scope, so it starts as all zeros. Anything read past
   the count is therefore a clean zero rather than whatever the stack happened
   to hold -- a function that reads too far gets a wrong answer you can
   reproduce instead of one that changes between runs. */
static uint16_t samples[MAX_SAMPLES];

int main(void)
{
    unsigned long count = 0;
    unsigned long i;

    if (scanf("%lu", &count) != 1) {
        return 1;
    }
    if (count > MAX_SAMPLES) {
        return 1;
    }

    for (i = 0; i < count; i++) {
        unsigned int value;
        if (scanf("%u", &value) != 1) {
            return 1;
        }
        samples[i] = (uint16_t)value;
    }

    printf("%u\n", (unsigned int)average_samples(samples, (size_t)count));
    return 0;
}

