"""Random blocks of 12-bit ADC samples.

Block *length* is what matters here, so the shapes differ mainly in how many
samples they carry: one, a handful, and a long run. A block of exactly four is
never generated -- that length is already covered by a fixed case, and it is
the one length at which the interesting defect hides.
"""

MAX_SAMPLES = 64
FULL_SCALE = 4095


def generate(rng, count):
    builders = (_ramp, _noisy, _long_block, _flat)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, samples, description=""):
    body = " ".join(str(value) for value in samples)
    return {"name": name,
            "stdin": "%d\n%s\n" % (len(samples), body),
            "description": description}


def _length(rng, low, high):
    while True:
        n = rng.randint(low, high)
        if n != 4:
            return n


def _ramp(rng, index):
    n = _length(rng, 5, 12)
    step = FULL_SCALE // n
    start = rng.randrange(0, 200)
    samples = [min(start + step * i, FULL_SCALE) for i in range(n)]
    return _case("a rising ramp of %d #%d" % (n, index), samples,
                 "Steadily increasing, so an average taken over the wrong "
                 "number of samples lands well below the true one.")


def _noisy(rng, index):
    n = _length(rng, 6, 20)
    centre = rng.randint(500, 3500)
    samples = [max(0, min(FULL_SCALE, centre + rng.randint(-400, 400)))
               for _ in range(n)]
    return _case("%d samples around %d #%d" % (n, centre, index), samples,
                 "Realistic sensor noise about a steady level.")


def _long_block(rng, index):
    n = _length(rng, 40, MAX_SAMPLES)
    samples = [rng.randrange(0, FULL_SCALE + 1) for _ in range(n)]
    return _case("a full block of %d #%d" % (n, index), samples,
                 "Long enough that reading a fixed handful of elements is "
                 "obviously not reading the block.")


def _flat(rng, index):
    n = _length(rng, 5, 30)
    value = rng.randrange(0, FULL_SCALE + 1)
    return _case("%d samples all reading %d #%d" % (n, value, index),
                 [value] * n,
                 "A constant input, which hides any mistake that averages too "
                 "few of the samples: the mean of some of these readings is "
                 "the same as the mean of all of them.")
